<script setup lang="ts">
import CountryPool from './components/CountryPool.vue'
import AdminRegions from './components/AdminRegions.vue'
import {setSubscriptionRegions} from './lib'
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Globe2,Activity,Wallet,Users,ShieldCheck,Server,Plus,Settings2,ArrowUpRight,ArrowRight,RefreshCw,Download,Check,Clock3,Search,SearchX,AlertTriangle,Bell,Ticket,Package,Pencil,Trash2,FileText,Pause,Play,LockKeyhole,Copy} from 'lucide-vue-next'
import {api,action,cash,date,labels,orderLabel,orderTone,renewalAttention,notify,download,copy,key,subscriptionRegions,regionLabel,type Row} from './lib'
import {paymentNames} from './paymentJourney'
import {useOrderUpdates,serialRefresh,adminOrderConnection as orderConnection} from './orderUpdates'
import InviteManagement from './components/InviteManagement.vue'
import RiskMonitor from './components/RiskMonitor.vue'
import DataTable from './components/DataTable.vue'
import ProxyTable from './components/ProxyTable.vue'
import Modal from './components/Modal.vue'
import RegistrationPanel from './components/RegistrationPanel.vue'
import SystemUpdate from './components/SystemUpdate.vue'
import RegistrationControls from './components/RegistrationControls.vue'
import BillingEditor from './components/BillingEditor.vue'
import ConfigEditor from './components/ConfigEditor.vue'
import SiteControls from './components/SiteControls.vue'
import AdminCustomMenus from './components/AdminCustomMenus.vue'
import ProgressTrack from './components/ProgressTrack.vue'
import AdminMembership from './components/AdminMembership.vue'
import CheckoutResult from './components/CheckoutResult.vue'
import PaymentPanel from './components/PaymentPanel.vue'
import PaymentTrace from './components/PaymentTrace.vue'
import CheckoutLinks from './components/CheckoutLinks.vue'
import AdminRedeemUsage from './components/AdminRedeemUsage.vue'
import OrderBilling from './components/OrderBilling.vue'
const props=defineProps<{route:string;search?:string;user:Row}>();const emit=defineEmits<{refresh:[];'public-refresh':[]}>()
const routeParams=new URLSearchParams(props.search||'')
const data=ref<Row>({}),rows=ref<Row[]>([]),settings=ref<Row>({}),error=ref(''),busy=ref(false),loading=ref(true),selected=ref<string[]>([]),modal=ref(''),form=ref<Row>({}),detail=ref<Row>({}),codes=ref<string[]>([]),configGroup=ref(''),configTab=ref('site'),status=ref(routeParams.get('status')||'')
const proxyTab=ref('manual'),switchingProxy=ref(false)
async function switchProxy(mode:string){if(switchingProxy.value)return;switchingProxy.value=true;error.value='';try{await api('/admin/proxy-mode','PUT',{mode});await load();emit('public-refresh');notify('当前代理模式已切换')}catch(e){error.value=(e as Error).message}finally{switchingProxy.value=false}}
const canDeleteOrder=(row:Row)=>row.status!=='processing'
const orderAttention=ref(routeParams.get('attention')||'')
const orderSearch=ref(routeParams.get('order_id')||''),orderPage=ref(1),accountOptions=ref<Row>({tiers:[],products:[]})
const mutationKey=ref(key())
const page=computed(()=>props.route.replace('/admin','').slice(1)||'overview')
const subscriptionResources=computed(()=>['resources','regions','billing'].includes(page.value))
const resourceTabs=[{page:'resources',label:'订阅代理'},{page:'regions',label:'订阅地区'},{page:'billing',label:'订阅资料'}]
const orderStats=[{key:'queued',label:'排队中'},{key:'running',label:'办理中'},{key:'review',label:'付款待核实'},{key:'followup',label:'已付款待跟进'},{key:'completed',label:'已完成'},{key:'closed',label:'失败 / 已取消'}]
const titles:Row={regions:'订阅地区管理',invites:'邀请管理',membership:'会员管理',overview:'运营概览',orders:'订单中心',finance:'资金中心',users:'账户管理',topups:'充值审核',codes:'兑换码管理',products:'服务与定价',risk:'风控监控',resources:'订阅代理',billing:'订阅资料',announcements:'公告中心',audit:'操作审计',settings:'站点设置'}
const subtitles:Row={regions:'管理可选国家与结算币种，调整排序和开放状态。',invites:'管理伙伴邀请、奖励规则和积分入账，邀请关系与客户伙伴计划同步。',membership:'管理消费等级、客户权益及指定等级，变更记录纳入操作审计。',overview:'从经营、资金到服务状态，聚焦真正需要关注的变化。',orders:'每笔订单有迹可循，详细阶段与处理记录尽在掌握。',finance:'按时间与账户核对入账、消费及余额，默认排除管理员。',users:'集中管理账户权限、服务单价和资金调整。',topups:'核实真实到账后再入账，每次审核都有记录。',codes:'按面值发行、批量管理，并导出一行一个的 TXT。',products:'配置服务展示与标准报价，历史订单保留当时价格。',risk:'定位异常请求和访问来源，在风险扩大前及时处理。',resources:'配置订阅代理、排队并发与重试策略。',billing:'管理订阅付款使用的持卡人及账单地址资料。',announcements:'将重要消息送到登录页与客户工作台。',audit:'敏感操作可追溯，记录操作者、时间、来源和结果。',settings:'塑造你的品牌，管理服务约定与平台基础配置。'}
const codesUsage=ref(false),codesUsageOpened=ref(false)
const codePage=ref(1),codeSearch=ref(''),codeStatus=ref('')
const codeQuery=()=>`?q=${encodeURIComponent(codeSearch.value)}&status=${codeStatus.value}&page=${codePage.value}&page_size=100`
const filteredRows=computed(()=>status.value?rows.value.filter(x=>x.status===status.value):rows.value)
const topupPending=computed(()=>rows.value.filter(x=>x.status==='pending').length)
const orderCols=[{key:'order',label:'订单 / 订阅账号'},{key:'owner',label:'所属客户'},{key:'product_name',label:'套餐'},{key:'fee',label:'服务费报价'},{key:'status',label:'处理状态'},{key:'source',label:'来源'},{key:'created_at',label:'创建时间'},{key:'action',label:'操作'}]
async function load(){error.value='';loading.value=true;try{selected.value=[];if(['membership','invites','regions'].includes(page.value)){}else if(page.value==='risk'){}else if(['settings','billing'].includes(page.value)){settings.value=await api('/admin/settings')}else{const result=await api('/admin/'+page.value+(page.value==='orders'?`?q=${encodeURIComponent(orderSearch.value)}&status=${status.value}&attention=${orderAttention.value}&include_admin=${routeParams.get('include_admin')||'true'}&page=${orderPage.value}&page_size=100`:page.value==='codes'?codeQuery():page.value==='topups'?`?status=${status.value}&include_admin=${routeParams.get('include_admin')||'true'}`:''));rows.value=result.items;if(['orders','codes'].includes(page.value))data.value=result;if(page.value==='users')accountOptions.value={tiers:result.tiers,products:result.products};if(page.value==='resources'){settings.value=await api('/admin/settings');setSubscriptionRegions((await api('/admin/regions')).items)}}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;await action(fn);busy.value=false}
async function config(group:string){await action(async()=>{settings.value=await api('/admin/settings');configGroup.value=group;modal.value='config'})}
function open(kind:string,row:Row={}){form.value=JSON.parse(JSON.stringify(row));mutationKey.value=key();if(kind==='user'){form.value={email:'',name:'',role:'member',status:'active',password:'',...form.value,fee_R:row.fee_override==null?'':Number(row.fee_override)/100,membership_code:row.membership_code||'',membership_until:row.membership_until?new Date(new Date(row.membership_until).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'',product_prices_R:Object.fromEntries((accountOptions.value.products||[]).map((p:Row)=>[p.id,row.product_prices?.[p.id]==null?'':row.product_prices[p.id]/100]))}}if(kind==='user'){form.value.original_membership_until=row.membership_until||null;form.value.original_membership_input=form.value.membership_until}if(kind==='balance')form.value={id:row.id,email:row.email,amount_R:0,reason:''};if(kind==='pricing')form.value={fee_R:''};if(kind==='codes')form.value={count:10,amount_R:100,days:365};if(kind==='product')form.value.fee_R=Number(row.fee)/100;if(kind==='announcement')form.value={title:'',body:'',tone:'info',published:false,login_visible:true,sort:0,starts_at:null,ends_at:null,...form.value};if(kind==='resource')form.value={name:'',endpoint:'',country:'PH',vendor:'other',ip_mode:'dynamic',enabled:true,weight:1,capacity:1,...form.value};if(kind==='block')form.value={ip:row.ip||'',minutes:60,reason:''};if(kind==='announcement'){for(const k of ['starts_at','ends_at'])if(form.value[k]){const d=new Date(form.value[k]);form.value[k]=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}}modal.value=kind}
async function order(row:Row){await action(async()=>{detail.value=await api('/admin/orders/'+row.id);rows.value=rows.value.map(r=>r.id===row.id?{...r,...detail.value.order,payment:detail.value.payment}:r);form.value={note:detail.value.order.note};modal.value='order'})}
const userOptions=(f:Row)=>({membership_code:f.membership_code,membership_until:f.membership_code&&f.membership_until?(f.membership_until===f.original_membership_input?f.original_membership_until:new Date(f.membership_until).toISOString()):null,product_prices:Object.fromEntries(Object.entries(f.product_prices_R||{}).filter(([,v])=>v!==''&&v!==null).map(([id,v])=>[id,Math.round(Number(v)*100)]))})
const accountDeleteResult=ref<Row|null>(null)
function confirmDeleteAccounts(ids:string[]){form.value={ids:[...ids],accounts:rows.value.filter(row=>ids.includes(row.id)).map(row=>({id:row.id,email:row.email,name:row.name}))};accountDeleteResult.value=null;modal.value='deleteAccounts'}
async function deleteAccounts(){await run(async()=>{const ids=form.value.ids;const result=ids.length===1?await api('/admin/users/'+ids[0],'DELETE'):await api('/admin/users/batch-delete','POST',{ids});accountDeleteResult.value=result;await load();emit('refresh');if(!result.skipped.length){modal.value='';notify(`已删除 ${result.deleted} 个账户`)}else notify(`已删除 ${result.deleted} 个账户，${result.skipped.length} 个账户未删除`)})}
async function deleteOrders(){const ids=[...selected.value];await run(async()=>{const result=await api('/admin/orders/batch-delete','POST',{ids});notify(`已删除 ${result.deleted} 笔订单，释放冻结服务费 ${cash(result.released)} 积分，客户订单同步移除${result.skipped?`；${result.skipped} 笔正在执行，已跳过`:""}`);await load()})}
async function save(){await run(async()=>{const f=form.value;switch(modal.value){case 'user':if(f.id)await api('/admin/users/'+f.id,'PATCH',{email:f.email,name:f.name,role:f.role,status:f.status,fee_override:f.fee_R===''?null:Math.round(f.fee_R*100),password:f.password||'',...userOptions(f)});else await api('/admin/users','POST',{email:f.email,name:f.name,role:f.role,password:f.password,...userOptions(f)});emit('refresh');break;case 'balance':await api('/admin/users/'+f.id+'/balance','POST',{amount:Math.round(f.amount_R*100),reason:f.reason},{'Idempotency-Key':mutationKey.value});emit('refresh');break;case 'pricing':await api('/admin/users/pricing','POST',{ids:selected.value,fee_override:f.fee_R===''?null:Math.round(f.fee_R*100)});break;case 'review':await api('/admin/topups/'+f.id+'/review','POST',{action:f.action,note:f.note});break;case 'codes':{const v=await api('/admin/codes','POST',{count:f.count,amount:Math.round(f.amount_R*100),days:f.days});codes.value=v.codes;download('starbridge-'+v.batch+'.txt',v.codes.join('\r\n'));break}case 'product':await api('/admin/products/'+f.id,'PUT',{name:f.name,description:f.description,fee:Math.round(f.fee_R*100),enabled:f.enabled,sort:f.sort,tag:f.tag,features:f.features});emit('public-refresh');break;case 'announcement':await api('/admin/announcements'+(f.id?'/'+f.id:''),f.id?'PUT':'POST',{title:f.title,body:f.body,tone:f.tone,published:f.published,login_visible:f.login_visible,sort:f.sort,starts_at:f.starts_at?new Date(f.starts_at).toISOString():null,ends_at:f.ends_at?new Date(f.ends_at).toISOString():null});emit('public-refresh');break;case 'resource':await api('/admin/resources'+(f.id?'/'+f.id:''),f.id?'PUT':'POST',{name:f.name,endpoint:f.endpoint,country:f.country,vendor:f.vendor,ip_mode:f.ip_mode,enabled:f.enabled,weight:f.weight,capacity:f.capacity,is_global:!!f.is_global});break;case 'block':await api('/admin/blocks','POST',f);break;case 'order':await api('/admin/orders/'+detail.value.order.id,'PATCH',{note:f.note});break};notify('操作已完成');modal.value='';await load()})}
async function copyCodes(ids:string[]){await run(async()=>{const v=await api('/admin/codes/batch','POST',{ids,action:'copy'});if(!v.codes.length)throw new Error('所选兑换码已不存在，请刷新列表');await copy(v.codes.join('\n'));notify(`已复制 ${v.codes.length} 个兑换码，每个占一行`)})}
async function batchCodes(operation:string){if(!selected.value.length){notify('请先选择兑换码');return}if(operation!=='export'){form.value={operation,ids:[...selected.value]};modal.value='codeConfirm';return}await run(async()=>{const v=await api('/admin/codes/batch','POST',{ids:selected.value,action:'export'});if(!v.codes.length)throw new Error('所选兑换码没有有效且未使用的码');download('starbridge-codes.txt',v.codes.join('\r\n'));notify(`已导出 ${v.changed} 个，跳过 ${v.skipped} 个不可用的码`)})}
const modalTitle=computed(()=>({user:form.value.id?'编辑账户':'创建账户',balance:'调整账户余额',pricing:'批量设置服务单价',review:'审核充值申请',codes:'发行兑换码',product:'编辑服务方案',announcement:form.value.id?'编辑公告':'发布新公告',resource:form.value.id?'编辑代理资源':'添加代理资源',block:'限制访问来源',order:'订单完整记录',config:'配置 · '+({risk:'风控规则',payment:'站内付款',scheduler:'队列调度',billing:'订阅资料',proxy:'代理设置',tiers:'会员等级'} as Row)[configGroup.value],deleteAccounts:'删除账户',delete:'确认删除',codeConfirm:'批量管理兑换码'} as Row)[modal.value]||'详情')
const liveError=ref('')
let disposed=false
const updateOrder=serialRefresh(async()=>{const id=detail.value.order?.id;if(modal.value!=='order'||!id)return;try{const v=await api('/admin/orders/'+id,'GET',undefined,{},AbortSignal.timeout(10000));if(!disposed&&modal.value==='order'&&detail.value.order?.id===id){detail.value=v;liveError.value=''}}catch{liveError.value='订单更新暂时失败，可点击刷新重试。'}})
useOrderUpdates(id=>{if(modal.value==='order'&&(!id||id===detail.value.order?.id))void updateOrder();else if(!busy.value&&!modal.value&&!selected.value.length&&['orders'].includes(page.value))void updateList()},{admin:true})
const updateList=serialRefresh(load)
onMounted(async()=>{await load();const id=routeParams.get('order_id');if(page.value==='orders'&&id)await order({id})});onUnmounted(()=>{disposed=true})
</script>
<template><div class="page-heading"><div><span class="eyebrow">OPERATIONS / {{subscriptionResources?'SUBSCRIPTION RESOURCES':page.toUpperCase()}}</span><h1>{{subscriptionResources?'订阅资源与调度':titles[page]}}</h1><p>{{subscriptionResources?'集中管理订阅代理、可用地区与订阅资料，配置排队与执行策略。':subtitles[page]}}</p></div><div class="actions"><button v-if="!['orders','risk','invites','regions','billing'].includes(page)&&!codesUsage" class="icon-btn bordered" @click="load" :disabled="loading" aria-label="刷新数据"><RefreshCw :size="17" :class="{spinning:loading}"/></button><button v-if="page==='users'" class="btn primary" @click="open('user')"><Plus :size="17"/>创建账户</button><button v-if="page==='codes'" class="btn primary" @click="open('codes')"><Plus :size="17"/>发行兑换码</button><button v-if="page==='announcements'" class="btn primary" @click="open('announcement')"><Plus :size="17"/>新建公告</button><button v-if="page==='resources'&&proxyTab==='manual'" class="btn primary" @click="open('resource')"><Plus :size="17"/>添加资源</button><button v-if="page==='products'" class="btn secondary" @click="config('tiers')"><Settings2 :size="17"/>会员等级</button></div></div><div v-if="error" class="alert danger">{{error}}<button @click="load">重试</button></div>
<nav v-if="subscriptionResources" class="subscription-resource-tabs" aria-label="订阅资源分类"><a v-for="tab in resourceTabs" :key="tab.page" :href="'#/admin/'+tab.page" :class="{active:page===tab.page}" :aria-current="page===tab.page?'page':undefined">{{tab.label}}</a></nav>
<template v-if="page==='orders'"><div v-if="data.summary" class="order-center-summary" aria-label="订阅订单统计" :aria-busy="loading"><article v-for="item in orderStats" :key="item.key" class="order-center-summary-card"><span>{{item.label}}</span><b>{{Number(data.summary[item.key]).toLocaleString()}}</b></article></div><p v-if="orderAttention" class="callout">当前仅显示{{orderAttention==='followup'?'已付款、后续待处理':'办理中'}}的订单。<button class="text-btn" @click="orderAttention='';load()">清除条件</button></p><section class="panel record-panel"><div class="records-heading"><div><h2>全部订单</h2><p>付款、生效与续费分别记录，查看详情可跟进完整进度。</p></div><div class="order-heading-actions"><button class="btn secondary" @click="config('payment')"><Settings2 :size="15"/>订阅流程配置</button><button class="btn secondary" @click="load" :disabled="loading"><RefreshCw :size="15" :class="{'records-spin':loading}"/>刷新</button></div></div><form class="records-filters" @submit.prevent="orderPage=1;load()"><label class="records-search"><Search :size="16"/><input v-model="orderSearch" type="search" maxlength="200" placeholder="搜索订单号 / 订阅邮箱 / 客户 / 套餐" aria-label="搜索全部订单"/></label><label><select v-model="status" aria-label="订单状态" @change="orderPage=1;load()"><option value="">全部办理状态</option><option v-for="s in ['draft','queued','processing','awaiting_payment','review','succeeded','failed','cancelled']" :key="s" :value="s">{{labels[s]}}</option></select></label><button class="btn secondary" :disabled="loading">查询</button><button v-if="orderSearch||status" class="text-btn records-reset" type="button" @click="orderSearch='';status='';orderPage=1;load()">重置</button><button class="btn secondary danger-text" type="button" :disabled="!selected.length||busy" @click="deleteOrders"><Trash2 :size="15"/>批量删除（{{selected.length}}）</button></form><div class="records-count" role="status"><span><b>{{data.total||0}}</b> 条记录 · 全部订阅订单</span><span v-if="loading">正在刷新…</span></div><DataTable :rows="filteredRows" :columns="orderCols" selectable :can-select="canDeleteOrder" :searchable="false" :page-size="100" hide-pagination hide-toolbar @selection="selected=$event"><template #empty><SearchX :size="28"/><b>{{loading?'正在读取记录…':orderSearch||status?'没有符合条件的记录':'暂时没有记录'}}</b><p>{{orderSearch||status?'试试其他关键词，或清除筛选条件。':'新的业务记录会显示在这里。'}}</p></template><template #order="{row}"><b>{{row.email}}</b><small class="mono">{{row.id.slice(0,12)}}</small></template><template #fee="{row}">{{cash(row.fee)}} 积分</template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #source="{row}">{{row.source==='api'?'API 接入':'客户页面'}}</template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button class="text-btn" @click="order(row)">完整流程</button></template></DataTable><div class="records-pagination"><span>共 {{data.total||0}} 笔 · 每页 100 笔</span><div><button class="btn secondary" :disabled="orderPage===1||loading" @click="orderPage--;load()">上一页</button><span>{{orderPage}}</span><button class="btn secondary" :disabled="!data.has_more||loading" @click="orderPage++;load()">下一页</button></div></div></section></template>
<AdminRegions v-else-if="page==='regions'" @changed="emit('public-refresh')"/><InviteManagement v-else-if="page==='invites'" @changed="emit('refresh');emit('public-refresh')"/><AdminMembership v-else-if="page==='membership'" @changed="emit('refresh');emit('public-refresh')"/><template v-else-if="page==='users'"><div class="filter-strip"><span class="muted">已选 {{selected.length}} 个账号</span><button class="btn secondary" :disabled="!selected.length" @click="open('pricing')"><Settings2 :size="16"/>批量调整服务单价</button><button class="btn secondary danger-text" :disabled="!selected.length||busy" @click="confirmDeleteAccounts(selected)"><Trash2 :size="16"/>批量删除（{{selected.length}}）</button></div><div class="panel"><DataTable :rows="rows" selectable @selection="selected=$event" :columns="[{key:'account',label:'账户'},{key:'created_at',label:'注册时间'},{key:'role',label:'权限 / 状态'},{key:'balance',label:'可用余额'},{key:'frozen',label:'冻结余额'},{key:'membership',label:'会员等级'},{key:'fee_override',label:'账户通用价'},{key:'orders',label:'订单'},{key:'action',label:'操作'}]"><template #created_at="{row}">{{date(row.created_at)}}</template><template #account="{row}"><b>{{row.name}}</b><small>{{row.email}}</small></template><template #membership="{row}">{{row.membership?.current?.name}}<small>{{row.membership?.source==='manual'?'指定等级':'自动等级'}}</small></template><template #role="{row}"><span class="badge" :class="row.status">{{labels[row.role]}} · {{labels[row.status]}}</span></template><template #balance="{row}">{{cash(Number(row.balance||0)-Number(row.frozen||0))}} 积分</template><template #frozen="{row}">{{cash(row.frozen)}} 积分</template><template #fee_override="{row}">{{row.fee_override==null?'按等级':cash(row.fee_override)+' 积分'}}</template><template #action="{row}"><div class="actions"><button class="text-btn" @click="open('user',row)">编辑</button><button class="text-btn" @click="open('balance',row)">调账</button><button class="text-btn danger-text" :disabled="busy||row.id===user.id" :title="row.id===user.id?'不能删除当前登录的管理员':'删除账户'" @click="confirmDeleteAccounts([row.id])">删除</button></div></template></DataTable></div></template>
<template v-else-if="page==='topups'"><p v-if="status==='pending'" class="callout">当前只显示待审核充值。<button class="text-btn" @click="status='';load()">查看全部充值</button></p><div class="callout"><Wallet :size="18"/>待审核 {{topupPending}} 笔。只有核实真实到账后才确认入账，同一申请不会重复加款。</div><div class="panel"><DataTable :rows="rows" :columns="[{key:'email',label:'客户'},{key:'amount',label:'申请金额'},{key:'proof',label:'客户提供的核对信息'},{key:'status',label:'审核状态'},{key:'created_at',label:'申请时间'},{key:'action',label:'操作'}]"><template #amount="{row}"><b>{{cash(row.amount)}} 积分</b></template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #created_at="{row}">{{date(row.created_at)}}</template><template #action="{row}"><button v-if="row.status==='pending'" class="text-btn" @click="open('review',{...row,action:'approve',note:''})">审核</button><span v-else class="muted">{{row.note||'—'}}</span></template></DataTable></div></template>
<template v-else-if="page==='codes'"><div class="business-tabs code-tabs" role="tablist" aria-label="兑换码页面"><button role="tab" :aria-selected="!codesUsage" :class="{active:!codesUsage}" @click="codesUsage=false">兑换码列表</button><button role="tab" :aria-selected="codesUsage" :class="{active:codesUsage}" @click="codesUsage=true;codesUsageOpened=true">使用记录</button></div><AdminRedeemUsage v-if="codesUsageOpened" v-show="codesUsage"/><div v-show="!codesUsage"><form class="filter-strip" @submit.prevent="codePage=1;load()"><input v-model="codeSearch" maxlength="200" placeholder="搜索兑换码标识、批次或兑换账户" aria-label="搜索兑换码"/><select v-model="codeStatus" aria-label="兑换码状态" @change="codePage=1;load()"><option value="">全部状态</option><option value="active">可用</option><option value="used">已兑换</option><option value="disabled">已停用</option><option value="expired">已过期</option></select><button class="btn secondary" :disabled="loading">查询</button></form><div class="filter-strip"><span class="muted">已选 {{selected.length}} 条</span><button class="btn secondary" :disabled="!selected.length||busy" @click="copyCodes(rows.filter(r=>selected.includes(r.id)).map(r=>r.id))"><Copy :size="16"/>批量复制</button><button class="btn secondary" :disabled="!selected.length||busy" @click="batchCodes('export')"><Download :size="16"/>导出 TXT</button><button class="btn secondary" :disabled="!selected.length||busy" @click="batchCodes('disable')">批量停用</button><button class="btn secondary danger-text" :disabled="!selected.length||busy" @click="batchCodes('delete')">批量删除</button></div><div class="panel"><DataTable :key="codePage+codeStatus+codeSearch" :rows="rows" :page-size="100" hide-pagination :searchable="false" selectable @selection="selected=$event" :columns="[{key:'prefix',label:'兑换码标识'},{key:'amount',label:'面值'},{key:'batch',label:'发行批次'},{key:'status',label:'状态'},{key:'used_by',label:'兑换账户'},{key:'expires_at',label:'到期时间'},{key:'action',label:'操作'}]"><template #prefix="{row}"><code>{{row.prefix}}</code></template><template #amount="{row}">{{cash(row.amount)}} 积分</template><template #status="{row}"><span class="badge order-status" :class="orderTone(row)">{{orderLabel(row)}}</span></template><template #expires_at="{row}">{{date(row.expires_at)}}</template><template #action="{row}"><button class="text-btn" :disabled="busy" @click="copyCodes([row.id])"><Copy :size="14"/>复制</button></template></DataTable></div><div class="pagination"><span>共 {{data.total||0}} 个 · 每页 100 个</span><div><button class="btn secondary" :disabled="codePage===1||loading" @click="codePage--;load()">上一页</button><span>{{codePage}} / {{Math.max(1,Math.ceil((data.total||0)/100))}}</span><button class="btn secondary" :disabled="!data.has_more||loading" @click="codePage++;load()">下一页</button></div></div></div></template>
<template v-else-if="page==='products'"><div class="service-grid admin-products"><article class="service-card" v-for="p in rows" :key="p.id"><div class="actions"><span class="pill">{{p.tag}}</span><span class="badge" :class="p.visible?'active':p.enabled?'pending':'disabled'">{{p.visible?'展示中':p.enabled?'未展示':'已隐藏'}}</span></div><h3>{{p.name}}</h3><p>{{p.description}}</p><p v-if="p.enabled && p.availability_reason" class="callout">{{p.availability_reason}}</p><div><b>{{cash(p.fee)}} 积分 <small>/ 次服务</small></b><button class="icon-btn bordered" @click="open('product',p)" :aria-label="'编辑 '+p.name"><Pencil :size="17"/></button></div></article></div><div class="callout">用户端仅展示已启用且当前订阅办理流程支持的套餐。上游订阅费用与平台服务费分开。<button class="text-btn" @click="config('payment')">配置订阅办理流程</button></div></template>
<template v-else-if="page==='risk'"><RiskMonitor @configure="config('risk')"/><details class="panel advanced-risk"><summary>访问规则、客户限制与统计</summary><RegistrationPanel route="/admin/risk-controls" :user="user" :pub="{}" :enabled="true" @refresh="emit('refresh')"/></details></template>
<template v-else-if="page==='resources'"><div class="ops-banner proxy-controls"><div><Server :size="20"/><b>当前模式：{{settings.proxy?.mode==='country_pool'?'国家代理池':'手动代理'}}</b></div><div class="actions"><button class="btn secondary" @click="config('scheduler')"><Settings2 :size="16"/>队列配置</button></div></div><div class="tabs"><button :class="{active:proxyTab==='manual'}" @click="proxyTab='manual'">手动代理</button><button :class="{active:proxyTab==='country_pool'}" @click="proxyTab='country_pool'">国家代理池</button></div><div class="filter-strip"><span class="muted">两种模式独立保存，只启用一种。正在办理的订单继续使用原会话。</span><button v-if="(settings.proxy?.mode||'manual')!==proxyTab" class="btn primary" :disabled="switchingProxy" @click="switchProxy(proxyTab)">{{switchingProxy?'检查占用中…':'启用'+(proxyTab==='manual'?'手动代理':'国家代理池')}}</button><span v-else class="badge active">当前已启用</span></div><CountryPool v-if="proxyTab==='country_pool'" :resources="rows" @changed="load();emit('public-refresh')"/><template v-else><div class="filter-strip"><button class="btn secondary" @click="config('proxy')"><Settings2 :size="16"/>手动代理配置</button></div><div class="global-proxy-banner"><Globe2 :size="20"/><div><b>续费全局代理：{{rows.find(r=>r.is_global)?.name||'尚未设置'}}</b><p>{{rows.find(r=>r.is_global)?.enabled?'续费管理菜单的独立取消与核实使用此代理；订阅办理全程沿用原订单代理。':'用于续费管理菜单。未配置、停用或占满时独立任务等待；订阅办理继续使用原订单代理。'}}</p></div></div><ProxyTable :rows="rows" :busy="busy" @refresh="load" @edit="open('resource',$event)" @remove="form={id:$event.id,path:'resources',name:$event.name};modal='delete'"/><div class="callout"><LockKeyhole :size="18"/>订阅办理按地区选择代理，整单沿用同一个端点。动态 IPRoyal 按订单国家替换 country 并添加独立 session，动态 Cliproxy 每单生成独立 sid、有效 15 分钟；静态和其他厂商原样使用后台凭据。代理会话按有效期使用，刷新账号 Session 和重试均不更换订单绑定。独立续费管理使用全局代理。评分只代表连接质量，不代表 IP 风险分。</div></template></template>
<template v-else-if="page==='announcements'"><div class="announcement-cards"><article class="panel announcement-admin" v-for="a in rows" :key="a.id"><div class="actions"><span class="badge" :class="a.published?'active':'draft'">{{a.published?'已发布':'草稿'}}</span><span class="pill" v-if="a.login_visible">登录页展示</span><span class="muted small">排序 {{a.sort}}</span></div><h2>{{a.title}}</h2><p class="pre-wrap">{{a.body}}</p><footer><span>{{a.starts_at?date(a.starts_at):'立即生效'}} / {{a.ends_at?date(a.ends_at):'长期有效'}}</span><div class="actions"><button class="text-btn" @click="open('announcement',a)">编辑</button><button class="text-btn danger-text" @click="form={id:a.id,path:'announcements',name:a.title};modal='delete'">删除</button></div></footer></article><div v-if="!rows.length" class="panel empty"><Bell :size="32"/><h3>把重要消息告诉客户</h3><p>支持多条公告、展示排序与定时上下线。</p><button class="btn primary" @click="open('announcement')">新建第一条公告</button></div></div></template>
<template v-else-if="page==='audit'"><div class="panel"><DataTable :rows="rows" :columns="[{key:'created_at',label:'时间'},{key:'actor',label:'操作者'},{key:'action',label:'操作'},{key:'target',label:'目标'},{key:'detail',label:'说明'},{key:'ip',label:'来源 IP'}]"><template #created_at="{row}">{{date(row.created_at)}}</template><template #target="{row}"><span class="mono">{{row.target?.length>20?row.target.slice(0,12)+'…':row.target}}</span></template></DataTable></div></template>
<template v-else-if="page==='billing'"><section v-if="settings.billing" class="panel subscription-profiles"><BillingEditor :value="settings.billing"/></section></template>
<template v-else-if="page==='settings'"><div class="tabs settings-tabs"><button v-for="[id,label] in [['features','功能开关'],['security','安全与认证'],['mail','邮件设置'],['custom_menus','自定义菜单']]" :key="id" :class="{active:configTab===id}" @click="configTab=id">{{label}}</button><button :class="{active:configTab==='site'}" @click="configTab='site'">品牌与服务</button><button :class="{active:configTab==='tiers'}" @click="configTab='tiers'">会员等级</button></div><SystemUpdate v-if="configTab==='security'"/><RegistrationControls v-if="configTab==='features'"/><div class="panel form-panel" :style="['features','mail','custom_menus'].includes(configTab)?{maxWidth:'none'}:{}" v-if="settings[configTab]"><AdminCustomMenus v-if="configTab==='custom_menus'" :value="settings.custom_menus" @saved="load();emit('public-refresh')"/><SiteControls v-else-if="['features','security','mail'].includes(configTab)" :key="configTab" :group="configTab" :value="settings[configTab]" @saved="load();emit('public-refresh')"/><ConfigEditor v-else :key="configTab" :group="configTab" :value="settings[configTab]" @saved="load();emit('public-refresh')"/></div></template>
<Modal v-if="modal" :title="modalTitle" :wide="['order','config'].includes(modal)" @close="modal=''">
<ConfigEditor v-if="modal==='config'" :group="configGroup" :value="settings[configGroup]" @saved="modal='';load();emit('public-refresh')"/>
<template v-else-if="modal==='deleteAccounts'"><template v-if="!accountDeleteResult"><p>确认删除以下 {{form.ids.length}} 个账户？删除后无法登录，现有登录会话和 API 密钥立即失效。</p><ul class="account-delete-list"><li v-for="account in form.accounts" :key="account.id"><b>{{account.name}}</b><span>{{account.email}}</span></li></ul><div class="callout">历史订单和资金流水保留用于对账，已受理任务继续完成。邮箱可以重新注册，新账号不继承原余额、订单或会员权益。</div><p class="muted small">当前登录的管理员和最后一个可用管理员不会被删除。</p><div class="actions"><button class="btn secondary" :disabled="busy" @click="modal=''">取消</button><button class="btn danger" :disabled="busy" @click="deleteAccounts">{{busy?'删除中…':'确认删除'}}</button></div></template><template v-else><p>已删除 {{accountDeleteResult.deleted}} 个账户，以下账户未删除：</p><ul class="account-delete-list"><li v-for="account in accountDeleteResult.skipped" :key="account.id"><b>{{account.email}}</b><span>{{account.reason}}</span></li></ul><button class="btn secondary" @click="modal=''">关闭</button></template></template>
<template v-else-if="modal==='delete'"><p>确认删除「{{form.name}}」？此操作会立即生效。</p><button class="btn danger" :disabled="busy" @click="run(async()=>{await api('/admin/'+form.path+'/'+form.id,'DELETE');modal='';await load();emit('public-refresh');notify('已删除')})">确认删除</button></template>
<template v-else-if="modal==='codeConfirm'"><p>对 {{form.ids.length}} 条记录执行{{form.operation==='delete'?'删除':'停用'}}。已兑换记录会保留，以便核对账本。</p><button class="btn danger" :disabled="busy" @click="run(async()=>{const result=await api('/admin/codes/batch','POST',{ids:form.ids,action:form.operation});modal='';await load();notify(`已处理 ${result.changed} 个，跳过 ${result.skipped} 个`)})">确认操作</button></template>
<form v-else @submit.prevent="save">
<template v-if="modal==='user'"><div class="form-grid"><label>邮箱<input type="email" v-model="form.email" required/></label><label>称呼<input v-model="form.name" required maxlength="80"/></label><label>角色<select v-model="form.role"><option value="member">客户</option><option value="admin">管理员</option></select></label><label v-if="form.id">状态<select v-model="form.status"><option value="active">可用</option><option value="disabled">停用</option></select></label><label class="span2">{{form.id?'重设密码（不修改留空）':'初始密码'}}<input type="password" v-model="form.password" :required="!form.id" minlength="10" maxlength="72" autocomplete="new-password"/></label><label>会员等级<select v-model="form.membership_code"><option value="">按消费自动计算</option><option v-for="t in accountOptions.tiers" :key="t.code" :value="t.code">{{t.code}} · {{t.name}}</option></select></label><label v-if="form.membership_code">会员有效至（留空为长期）<input type="datetime-local" v-model="form.membership_until"/></label><label v-if="form.id">账户通用服务单价（积分）<input v-model="form.fee_R" type="number" min="0" step="0.01" placeholder="留空：按会员等级"/></label><div class="span2"><h3>按套餐设置专属价格</h3><p class="muted small">套餐专属价格优先；留空时沿用账户通用价，没有通用价则按会员等级。填写 0 表示该套餐免服务费。</p><div class="form-grid"><label v-for="p in accountOptions.products" :key="p.id">{{p.name}}（积分）<input v-model="form.product_prices_R[p.id]" type="number" min="0" max="1000000" step="0.01" placeholder="留空：沿用原计价规则"/></label></div></div></div></template>
<template v-else-if="modal==='balance'"><p>{{form.email}}</p><div class="callout">正数增加余额，负数扣减余额；不会改变冻结金额，所有调整保留账本记录。</div><label>调整金额（积分）<div class="amount-control"><button type="button" @click="form.amount_R=Number(form.amount_R)-10">−</button><input v-model.number="form.amount_R" type="number" step="0.01" required/><button type="button" @click="form.amount_R=Number(form.amount_R)+10">+</button></div></label><label>调整原因<textarea v-model="form.reason" required minlength="2" maxlength="300" placeholder="请填写本次调整的业务依据"></textarea></label></template>
<template v-else-if="modal==='pricing'"><p>将调整选中的 {{selected.length}} 个账户，仅影响之后创建的订单。</p><label>专属服务单价（积分）<input v-model="form.fee_R" type="number" min="0" step="0.01" placeholder="留空恢复套餐与等级定价"/></label></template>
<template v-else-if="modal==='review'"><div class="review-amount"><span>{{form.email}}</span><strong>{{cash(form.amount)}} 积分</strong></div><div class="callout pre-wrap">客户备注：{{form.proof||'未填写'}}</div><label>审核结果<select v-model="form.action"><option value="approve">已核实真实到账，同意入账</option><option value="reject">未核实到账，拒绝申请</option></select></label><label>审核说明<textarea required minlength="2" maxlength="300" v-model="form.note" placeholder="到账渠道、时间、核对结果"></textarea></label></template>
<template v-else-if="modal==='codes'"><div class="form-grid"><label>生成数量<input v-model.number="form.count" type="number" min="1" max="200" required/></label><label>每个面值（积分）<input v-model.number="form.amount_R" type="number" min="1" max="100000" step="0.01" required/></label><label>有效天数<input v-model.number="form.days" type="number" min="1" max="3660" required/></label></div><div class="callout">生成后自动下载 TXT，每行一个兑换码。已发行不代表已入账，兑换成功后才进入账本。</div></template>
<template v-else-if="modal==='product'"><label>展示名称<input v-model="form.name" required maxlength="80"/></label><label>介绍<input v-model="form.description" maxlength="300"/></label><div class="form-grid"><label>服务费（积分）<input v-model.number="form.fee_R" required type="number" min="0" step="0.01"/></label><label>标签<input v-model="form.tag" maxlength="40"/></label><label>排序<input v-model.number="form.sort" type="number"/></label><label class="switch-label"><input type="checkbox" v-model="form.enabled"/>展示此服务</label></div></template>
<template v-else-if="modal==='announcement'"><label>标题<input v-model="form.title" maxlength="150" required/></label><label>公告正文<textarea v-model="form.body" rows="6" maxlength="5000" required></textarea></label><div class="form-grid"><label>提醒类型<select v-model="form.tone"><option value="info">普通通知</option><option value="warning">重要提醒</option><option value="success">服务动态</option></select></label><label>排序<input v-model.number="form.sort" type="number"/></label><label>开始时间（选填）<input v-model="form.starts_at" type="datetime-local"/></label><label>结束时间（选填）<input v-model="form.ends_at" type="datetime-local"/></label><label class="checkbox-label"><input v-model="form.published" type="checkbox"/>立即发布 / 按时生效</label><label class="checkbox-label"><input v-model="form.login_visible" type="checkbox"/>同时展示在登录页</label></div></template>
<template v-else-if="modal==='resource'"><label>资源名称<input v-model="form.name" maxlength="80" required/></label><div class="form-grid"><label>代理厂商<select v-model="form.vendor" required><option value="iproyal">IPRoyal</option><option value="cliproxy">Cliproxy</option><option value="other">其他</option></select></label><label>代理类型<select v-model="form.ip_mode" required><option value="dynamic">动态</option><option value="static">静态</option></select></label></div><p class="muted small">{{form.ip_mode==='dynamic'&&form.vendor==='iproyal'?'按订单所选国家替换 country，每笔订阅生成独立 session，整单复用同一会话。':form.ip_mode==='dynamic'&&form.vendor==='cliproxy'?'每笔订阅生成独立 sid，固定 15 分钟，整单复用同一会话。':'直接使用填写的代理凭据，不自动添加或改写 session。'}}地址、厂商和类型修改对后续任务生效，已有订单沿用原代理会话。</p><label>代理地址<input v-model="form.endpoint" :required="!form.id" placeholder="host:port:user:password 或 socks5://user:pass@host:port" autocomplete="off"/><small>默认 HTTP，也支持 HTTPS、SOCKS5、SOCKS5H。管理员列表和编辑页显示完整地址；地址修改只影响之后分配的订单。</small></label><div class="form-grid"><label>订阅地区<select v-model="form.country" required><option v-if="form.country&&!subscriptionRegions.some(r=>r.code===form.country)" :value="form.country" disabled>{{form.country}}（请重新选择）</option><option v-for="r in subscriptionRegions" :key="r.code" :value="r.code">{{r.name}} · {{r.code}} / {{r.currency}}</option></select><small>{{form.vendor==='iproyal'&&form.ip_mode==='dynamic'?'IPRoyal 动态代理按订单国家自动替换地址中的 country，此项不限制可办理国家。':'订单选择此地区时自动匹配本代理。'}}</small></label><label>单资源并发<input v-model.number="form.capacity" type="number" min="1" max="100" required/></label><label>权重<input v-model.number="form.weight" type="number" min="1" max="100" required/></label><label class="checkbox-label"><input v-model="form.enabled" type="checkbox"/>启用资源</label></div><label class="checkbox-label"><input v-model="form.is_global" type="checkbox"/>设为全局代理（独立续费管理）</label><p class="muted small">全局只能选一条；设置后替换原全局代理，不影响提链按地区匹配。</p></template>
<template v-else-if="modal==='block'"><label>来源 IP<input v-model="form.ip" required placeholder="公网 IPv4 或 IPv6"/></label><label>限制时长（分钟）<input v-model.number="form.minutes" type="number" min="1" max="10080" required/></label><label>原因<textarea v-model="form.reason" minlength="2" maxlength="300" required></textarea></label></template>
<template v-else-if="modal==='order'"><p class="live-status" role="status">{{orderConnection==='live'?'进度实时同步':orderConnection==='connecting'?'正在连接实时进度…':'实时连接中断，正在重连…'}} <button class="text-btn" @click="updateOrder">刷新</button></p><p v-if="liveError" class="alert danger">{{liveError}}</p><div class="detail-title"><div><h3>{{detail.order?.email}}</h3><p>{{detail.order?.owner}} / {{detail.order?.product_name}}</p><small class="mono">{{detail.order?.id}}</small><p v-if="detail.order?.checkout_flow">提链流程：<b>{{detail.order.checkout_flow==='legacy'?'旧提链':'新提链'}}</b><template v-if="detail.order.workflow==='subscription'"> → 付款及后续：<b>{{paymentNames[detail.order.subscription_flow]||'未记录'}}</b></template><template v-else> · 仅生成结账链接</template></p></div><span class="badge order-status" :class="orderTone(detail.order)">{{orderLabel(detail.order)}}</span></div><div v-if="detail.proxy" class="callout"><b>本单代理：{{detail.proxy.source_mode==='country_pool'?'国家代理池':'手动代理'}} · {{detail.order?.country}}</b><p>会话 {{detail.proxy.session_ref}} · 分配于 {{date(detail.proxy.created_at)}} · 到期 {{date(detail.proxy.expires_at)}}</p></div><ProgressTrack :status="detail.order?.status" :payment-state="detail.payment?.state" :workflow="detail.order?.workflow" :renewal="detail.order?.renewal" :activation="detail.order?.activation" :progress-stage="detail.order?.progress_stage"/><PaymentTrace :key="detail.order?.id" :order="detail.order" :payment="detail.payment" :billing="detail.billing" :checkout="detail.checkout" :links="detail.checkout_links||[]" :events="detail.trace||[]"/><CheckoutResult v-if="detail.order?.workflow!=='subscription'" :checkout="detail.checkout" :payment-state="detail.payment?.state"/><details class="business-records"><summary>已保存的结账链接 · {{(detail.checkout_links||[]).length}} 条</summary><CheckoutLinks :links="detail.checkout_links||[]"/></details><details class="business-records" :open="['review','action_required','preparing','quoted','submitting','checking'].includes(detail.payment?.state)"><summary>付款操作与详细状态</summary><PaymentPanel :order="detail.order" :payment="detail.payment" :admin="true" @refresh="order(detail.order)"/></details><div v-for="entry in detail.closures||[]" :key="entry.created_at" class="callout"><b>人工关闭记录</b><p>{{entry.actor}} · {{date(entry.created_at)}}</p><p>原因：{{entry.reason}}</p><p>关闭前付款状态：{{entry.prior_payment_state}}；{{entry.payment_submitted?'已提交过付款，需另行核实银行卡结果':'尚未提交付款'}}。冻结服务费已释放。</p></div><details class="business-records" v-if="detail.order?.workflow==='subscription'||detail.billing?.state!=='not_selected'"><summary>本单账单资料</summary><OrderBilling :billing="detail.billing"/></details><details class="business-records"><summary>业务记录与处理说明</summary><div class="timeline"><div v-for="(e,i) in detail.events" :key="i"><span class="timeline-dot"></span><small>{{date(e.created_at)}}</small><p>{{e.message}}</p></div></div></details><label>运营备注<textarea v-model="form.note" maxlength="1000" placeholder="仅记录业务处理依据，不要填写密钥或卡片信息"></textarea></label></template>
<div class="form-footer"><button type="button" class="btn secondary" @click="modal=''">取消</button><button class="btn primary" :disabled="busy"><Check :size="16"/>{{busy?'处理中…':modal==='codes'?'生成并导出 TXT':'确认保存'}}</button></div></form></Modal></template>

<style scoped>
.advanced-risk{margin-top:24px;padding:20px}.advanced-risk summary{cursor:pointer;font-weight:600;margin-bottom:16px}

.account-delete-list{max-height:240px;overflow:auto;list-style:none;padding:0;margin:20px 0}.account-delete-list li{display:flex;flex-direction:column;gap:6px;padding:12px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.account-delete-list span{color:var(--muted);font-size:13px}

.subscription-resource-tabs{display:flex;gap:0;border-bottom:1px solid var(--line);margin-bottom:22px;overflow-x:auto}.subscription-resource-tabs a{padding:13px 22px;white-space:nowrap;color:var(--muted);border-bottom:2px solid transparent;font-size:13px}.subscription-resource-tabs a.active{color:var(--green);border-bottom-color:var(--green);font-weight:600}@media(max-width:700px){.subscription-resource-tabs a{padding:12px 16px}}
.settings-tabs{overflow-x:auto;flex-wrap:nowrap}.settings-tabs button{white-space:nowrap;flex-shrink:0}

.global-proxy-banner{display:flex;align-items:center;gap:14px;background:#edf7f2;border:1px solid #d8eae1;padding:18px 22px;border-radius:12px;margin-bottom:20px;color:#237459}.global-proxy-banner p{font-size:12px;margin:6px 0 0;color:#55756a}
@media(max-width:700px){.proxy-controls{align-items:flex-start;flex-direction:column;gap:14px}.proxy-controls>.actions{flex-wrap:wrap}.proxy-controls>.actions>.btn{padding:10px 12px}.global-proxy-banner{padding:16px;align-items:flex-start}.global-proxy-banner>svg{flex-shrink:0}}
</style>

<style scoped>.code-tabs{display:flex;gap:4px;padding:5px;background:#edf3ef;border:1px solid var(--line);border-radius:11px;width:fit-content;margin-bottom:22px}.code-tabs button{padding:10px 24px;border-radius:7px;color:#647c70;font-weight:600}.code-tabs button.active{background:#fff;color:var(--green);box-shadow:0 1px 4px #183e2614}.code-tabs button:focus-visible{outline:2px solid var(--green)}</style>
